import numpy as np
W = np.array([0.41, 0.27, 0.16, 0.12, 0.80])
EL = np.array([0.28, 0.24, 0.19, 0.33])
ER = np.array([0.22, 0.31, 0.26, 0.18])
EP = np.zeros((4, 4))
for a, b, v in [(0, 3, 0.90), (3, 0, 1.30), (2, 1, 1.60), (1, 2, 1.10), (2, 3, 0.45), (3, 2, 0.70)]:
    EP[a, b] = v
ST = np.array([1.9, 1.4, 1.2, 0.7])
def _code(text):
    return np.array(['ACGU'.index(ch) for ch in text])
def _sig(t, n):
    t = np.asarray(t, dtype=float)
    if t.shape != (4, n + 2, n + 1):
        return -1.0
    z = t[0, 1, n]
    if not np.isfinite(z) or z <= 0.0:
        return -2.0
    k = np.arange(t.size, dtype=float).reshape(t.shape)
    return float(np.log(z) / 10.0 + np.sum(np.abs(t) / z * (1.0 + k % 7)) / t.size + np.sum(t / z * np.cos(k + .17)) / 9.0)
S = _code('GGCAUAGCCA')
assert np.allclose(_sig(compute_stacked_inside_weights(S.copy(), W.copy(), EL.copy(), ER.copy(), EP.copy(), ST.copy(), 3), 10), target)

